using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "SunBirthActionsTag", menuName = "Data/Battle/Battle Actions/Tags/SunBirthActionsTag", order = 0)]
public class SunBirthActionsTag : Tag
{
	[SerializeField]
	private BattleAction actionToUse;

	public override string GetTagDescription()
	{
		return string.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(base.TagIDDescription), actionToUse.GetActionName());
	}
}
